class Fortran90Builder(Builder, identifier="FORTRAN90"):
    """F90 Builder"""

    ASSIGNMENT_CLASS = F90AssignmentLine
    # _routine_cls = F90RoutineContainer
    # _comment_cls = F90CommentLine

    # def handle_group_instruction(self, instruction, context, buildargs):
    #     yield from super().handle_group_instruction(
    #         instruction, context, buildargs
    #     )

    # def handle_content_instruction(self, instruction, context, buildargs):
    #     yield from super().handle_content_instruction(
    #         instruction, context, buildargs
    #     )

    # def handle_routine_instruction(self, instruction, context, buildargs):
    #     yield from super().handle_routine_instruction(
    #         instruction, context, buildargs
    #     )

    # def handle_mapapply_instruction(self, instruction, context, buildargs):
    #     yield from super().handle_mapapply_instruction(
    #         instruction, context, buildargs
    #     )

    def handle_environment_instruction(self, instruction, context, buildargs):
        foo = F90CommentLine(context=context)
        lvar = F90MultiFrame(14)
        foo.requires(lvar)
        foo.set_line(
            f"I probably need a multiframe variable here. I will use {lvar.name}"
        )
        yield foo
        yield from super().handle_environment_instruction(
            instruction, context, buildargs
        )

    def handle_affine_instruction(self, instruction, context, buildargs):
        instruction_dict = instruction.apply_environment(
            context.environment
        ).contribute_to_dict()

        tgt0 = instruction_dict.get("tgt0")
        src0 = instruction_dict.get("src0")
        alpha = instruction_dict.get("alpha")
        beta = instruction_dict.get("beta")
        otgt = list(tgt0.offsets)
        osrc = list(src0.offsets)
        yield F90CommentLine(f"tgt0={tgt0.name} @ {otgt}", context=context)
        yield F90CommentLine(f"src0={src0.name} @ {osrc}", context=context)
        yield F90CommentLine(f"alpha = {alpha}", context=context)
        yield F90CommentLine(f"beta  = {beta}", context=context)
        x_var_real = context.namespace.find_assignment(type(src0), "real")
        x_var_imag = context.namespace.find_assignment(type(src0), "imag")
        y_var_real = context.namespace.find_assignment(type(tgt0), "real")
        y_var_imag = context.namespace.find_assignment(type(tgt0), "imag")
        x_var_offs = src0.offsets
        y_var_offs = tgt0.offsets
        a_real = alpha.real
        a_imag = alpha.imag
        b_real = beta.real
        b_imag = beta.imag
        yield F90AffineContainer(
            y_var_real,
            y_var_offs,
            a_real,
            x_var_real,
            x_var_offs,
            0.0,
            context=context,
        )
        yield F90AffineContainer(
            y_var_real,
            y_var_offs,
            -a_imag,
            x_var_imag,
            x_var_offs,
            b_real,
            context=context,
        )
        yield F90AffineContainer(
            y_var_imag,
            y_var_offs,
            a_real,
            x_var_imag,
            x_var_offs,
            0.0,
            context=context,
        )
        yield F90AffineContainer(
            y_var_imag,
            y_var_offs,
            a_imag,
            x_var_real,
            x_var_offs,
            b_imag,
            context=context,
        )

        # foo1 = CodeLine("! this is a test expression", context=context)
        # temp1 = foo1.request_unique(
        #     "test_some_constant",
        #     F90Constant,
        #     value=[32, 31, 30],
        #     # size=None,
        #     dtype="i64",
        # )
        # foo1.format(foo=f"{temp1} + 2")
        # foo1.requires(temp1)
        # yield foo1

        # foo2 = CodeLine("! this is another test expression", context=context)
        # temp2 = self.request_temp(
        #     foo2,
        #     "test_temporary1",
        #     F90LocalVariable,
        #     size=42,
        #     dtype="i64",
        # )
        # foo2.format(foo=f"{temp2} + 2")
        # foo2.requires(temp2)
        # yield foo2

        yield CodeLine("", context=context)

    def handle_generic_instruction(self, instruction, context, buildargs):
        yield from super().handle_generic_instruction(
            instruction, context, buildargs
        )
        # foo = CodeLine("! this is a test expression {foo}", context=context)
